"""Validation helpers for JSON generated by the language model."""

import json
from typing import Any, Type, TypeVar

from pydantic import BaseModel, TypeAdapter, ValidationError

ModelT = TypeVar("ModelT", bound=BaseModel)


def parse_json_object(text: str, model: Type[ModelT]) -> ModelT:
    try:
        payload: Any = json.loads(text)
        return model.model_validate(payload)
    except (json.JSONDecodeError, TypeError, ValidationError) as error:
        raise ValueError(f"Generated {model.__name__} failed validation") from error


def response_schema(model: Type[ModelT]) -> dict[str, Any]:
    return model.model_json_schema()


def parse_json_value(text: str, annotation: Any) -> Any:
    try:
        return TypeAdapter(annotation).validate_json(text)
    except (json.JSONDecodeError, TypeError, ValidationError) as error:
        raise ValueError("Generated structured output failed validation") from error
